import sys
import types

try:
    import concurrent.interpreters as interpreters
except ImportError:
    # The practice sandbox runs Python 3.11, which has no concurrent.interpreters (PEP 734, Python 3.14).
    # This stand-in has the same create / prepare_main / exec / close API, so your code runs unchanged
    # on 3.14. Keep this block as it is and write your answer below it.
    import concurrent

    class _Interpreter:
        def __init__(self):
            self._ns = {"__name__": "__main__"}

        def prepare_main(self, ns=None, /, **kwargs):
            self._ns.update(ns or {}, **kwargs)

        def exec(self, code):
            exec(code, self._ns)

        def close(self):
            self._ns = {}

    interpreters = types.ModuleType("concurrent.interpreters")
    interpreters.create = _Interpreter
    interpreters.PM_STAND_IN = True
    sys.modules["concurrent.interpreters"] = interpreters
    concurrent.interpreters = interpreters

import threading


def parallel_compute(values, code_template):
    # One interpreter per value: prepare_main(value=...), exec(code_template) in a thread,
    # wait for every thread, close every interpreter, and return how many ran.
    interps = []
    threads = []
    for v in values:
        interp = interpreters.create()
        interp.prepare_main(value=v)
        interps.append(interp)
        t = threading.Thread(target=interp.exec, args=(code_template,))
        threads.append(t)
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    for interp in interps:
        interp.close()
    return len(interps)
